# The MCP tool definition the agent sees when it lists available tools
SEARCH_TOOL = {
    "name": "search_docs",
    "description": (
        "Search the knowledge base for chunks relevant to a query. "
        "Call this before answering any question that needs facts from internal documents."
    ),
    "inputSchema": {
        "type": "object",
        "properties": {
            "query": {"type": "string", "description": "The natural language question or topic to search for"},
            "top_k": {"type": "integer", "description": "How many chunks to return", "default": 5}
        },
        "required": ["query"]
    }
}

{
  "tool_call": {
    "name": "search_docs",
    "arguments": { "query": "refund policy effective date", "top_k": 3 }
  },
  "tool_result": [
    { "text": "Refunds are processed within 14 days of the request date.", "source": "refund-policy", "score": 0.91 },
    { "text": "The updated refund window took effect on the first of last month.", "source": "refund-policy", "score": 0.88 },
    { "text": "Store credit is issued when a receipt cannot be located.", "source": "refund-policy", "score": 0.74 }
  ]
}
